package com.personal.novellibrary.data

import androidx.room.*

enum class Genre { FANTASY, MODERN_FANTASY, WUXIA, ROMANCE, ROMANCE_FANTASY, BL, GL, MYSTERY, THRILLER, HORROR, SF, GAME, HISTORY, DRAMA, LIGHT_NOVEL, ETC, UNCLASSIFIED }
enum class ReadingStatus { UNREAD, PLAN_TO_READ, READING, READ, DROPPED, DISLIKED }
enum class PlatformType { NOVELPIA, MUNPIA, NAVER_SERIES, KAKAO_PAGE, RIDI }
enum class LookupStatus { NOT_REQUESTED, LOADING, SUCCESS, NO_RESULT, FAILED, NEEDS_USER_CONFIRMATION, MANUAL, EXCLUDED }
enum class CollectionType { NORMAL, SMART }
enum class JobStatus { QUEUED, RUNNING, SUCCESS, NO_RESULT, FAILED, CANCELLED }

@Entity(indices=[Index("normalizedTitle"), Index("author"), Index("mainGenre"), Index("isFavorite"), Index("readingStatus"), Index("lastFetchedAt"), Index("isDeleted"), Index("isInfoLocked")])
data class NovelEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val displayTitle:String, val normalizedTitle:String, val confirmedTitle:String?=null, val author:String?=null, val mainGenre:Genre=Genre.UNCLASSIFIED, val synopsis:String?=null, val serializationStatus:String?=null, val isCompleted:Boolean?=null, val coverUrl:String?=null, val isFavorite:Boolean=false, val readingStatus:ReadingStatus=ReadingStatus.UNREAD, val personalRating:Float?=null, val memo:String?=null, val readingStartedAt:Long?=null, val completedAt:Long?=null, val droppedAt:Long?=null, val lastReadChapter:String?=null, val rereadCount:Int=0, val readingNote:String?=null, val manualSourceNote:String?=null, val isHidden:Boolean=false, val isDeleted:Boolean=false, val isInfoLocked:Boolean=false, val createdAt:Long=System.currentTimeMillis(), val updatedAt:Long=System.currentTimeMillis(), val lastViewedAt:Long?=null, val lastFetchedAt:Long?=null)
@Entity(foreignKeys=[ForeignKey(entity=NovelEntity::class,parentColumns=["id"],childColumns=["novelId"],onDelete=ForeignKey.CASCADE)], indices=[Index("novelId"), Index("documentUri", unique=true)])
data class LocalFileEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val novelId:Long, val documentUri:String, val originalFileName:String, val fileSize:Long, val lastModified:Long, val isAvailable:Boolean=true, val lastScannedAt:Long=System.currentTimeMillis())
@Entity(foreignKeys=[ForeignKey(entity=NovelEntity::class,parentColumns=["id"],childColumns=["novelId"],onDelete=ForeignKey.CASCADE)], indices=[Index("novelId"), Index("platformType"), Index("lookupStatus"), Index(value=["novelId", "platformType"], unique=true)])
data class PlatformListingEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val novelId:Long, val platformType:PlatformType, val platformWorkId:String?=null, val platformTitle:String?=null, val platformAuthor:String?=null, val synopsis:String?=null, val genre:String?=null, val tags:String?=null, val status:String?=null, val rating:Float?=null, val ratingCount:Int?=null, val reviewCount:Int?=null, val coverUrl:String?=null, val detailUrl:String?=null, val matchConfidence:Int=0, val lookupStatus:LookupStatus=LookupStatus.NOT_REQUESTED, val lastFetchedAt:Long?=null, val errorMessage:String?=null, val isExcluded:Boolean=false)
@Entity(foreignKeys=[ForeignKey(entity=PlatformListingEntity::class,parentColumns=["id"],childColumns=["platformListingId"],onDelete=ForeignKey.CASCADE)], indices=[Index("platformListingId")]) data class ReviewSnapshotEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val platformListingId:Long, val reviewText:String, val reviewRating:Float?=null, val reviewerDisplayName:String?=null, val reviewDate:String?=null, val sortOrder:Int=0, val fetchedAt:Long=System.currentTimeMillis())
@Entity(foreignKeys=[ForeignKey(entity=NovelEntity::class,parentColumns=["id"],childColumns=["novelId"],onDelete=ForeignKey.CASCADE)], indices=[Index("novelId"), Index("alias")]) data class AliasEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val novelId:Long, val alias:String, val aliasType:String="ALIAS", val createdAt:Long=System.currentTimeMillis())
@Entity(indices=[Index("name", unique=true)]) data class UserTagEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val name:String, val createdAt:Long=System.currentTimeMillis())
@Entity(primaryKeys=["novelId","tagId"]) data class NovelUserTagCrossRef(val novelId:Long, val tagId:Long)
@Entity data class CollectionEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val name:String, val description:String?=null, val collectionType:CollectionType=CollectionType.NORMAL, val filterJson:String?=null, val createdAt:Long=System.currentTimeMillis(), val updatedAt:Long=System.currentTimeMillis())
@Entity(primaryKeys=["collectionId","novelId"]) data class CollectionItemEntity(val collectionId:Long, val novelId:Long, val addedAt:Long=System.currentTimeMillis(), val sortOrder:Int=0)
@Entity data class SearchCandidateEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val novelId:Long, val platformType:PlatformType, val candidateTitle:String, val candidateAuthor:String?=null, val candidateSynopsis:String?=null, val candidateGenre:String?=null, val candidateCoverUrl:String?=null, val candidateWorkId:String?=null, val confidence:Int=0, val status:LookupStatus=LookupStatus.NEEDS_USER_CONFIRMATION)
@Entity data class ExcludedCandidateEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val novelId:Long, val platformType:PlatformType, val candidateWorkId:String?=null, val candidateTitle:String, val reason:String?=null, val createdAt:Long=System.currentTimeMillis())
@Entity data class SyncJobEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val novelId:Long, val platformType:PlatformType, val jobType:String, val status:JobStatus=JobStatus.QUEUED, val attemptCount:Int=0, val createdAt:Long=System.currentTimeMillis(), val startedAt:Long?=null, val finishedAt:Long?=null, val errorMessage:String?=null)
@Entity data class ChangeHistoryEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val novelId:Long, val actionType:String, val beforeValue:String?=null, val afterValue:String?=null, val createdAt:Long=System.currentTimeMillis(), val isUndoable:Boolean=true)
@Entity data class TrashEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val novelId:Long, val deletedAt:Long=System.currentTimeMillis(), val scheduledPurgeAt:Long=deletedAt + 30L*24*60*60*1000)
